function bytes(value){const n=Number(value)||0;if(n<1024)return n+' B';const i=Math.min(4,Math.floor(Math.log(n)/Math.log(1024)));return (n/1024**i).toFixed(i>1?1:0)+' '+['B','KiB','MiB','GiB','TiB'][i];}
