async function browse(kind,extensions,multiple=false){const selected=await bridge.call(kind==='folder'?'dialogs.openFolder':'dialogs.openFile',kind==='folder'?{title:t('Выберите папку','Choose a folder','Escolha uma pasta')}:{title:t('Выберите файл','Choose a file','Escolha um arquivo'),extensions,multiple});const paths=Array.isArray(selected)?selected:selected?[selected]:[];for(const file of paths)await api('paths.approve',{path:file});return multiple?paths:paths[0]||'';}
