function form(title,description,definitions,submit,label=t('Выполнить','Run','Executar'),options={}){const form=el('form');const fields=definitions.map(field);const grid=el('div',{class:options.grid?'form-grid':'form-fields'},fields.map(f=>f.wrapper));const output=el('div',{class:'form-output'});const run=el('button',{class:options.danger?'danger':'primary',type:'submit',text:label});form.append(grid,el('div',{class:'actions'},run),output);
  form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;run.disabled=true;output.replaceChildren();try{const input={};for(const f of fields){let value=f.def.type==='checkbox'?f.input.checked:f.input.value;if(f.def.type==='number')value=Number(value);if(f.def.type==='files')value=value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(f.def.type==='path'&&value)await api('paths.approve',{path:value});if(f.def.type==='files')for(const file of value)await api('paths.approve',{path:file});input[f.def.key]=value;}const result=await submit(input,output);if(result!==undefined)output.append(resultBox(result));}catch(error){output.append(el('div',{class:'notice error',text:error.message}));errorNotice(error);}finally{run.disabled=false;}});
  const section=card(title,description,form);section.fields=Object.fromEntries(fields.map(f=>[f.def.key,f.input]));return section;
}
