async function refreshJobs(){const list=await bridge.call('jobs.list');for(const job of list)updateJob(job);updateNavBadge();if(activeView==='downloads')renderJobs();}
function updateJob(job){jobs.set(job.id,job);updateNavBadge();const cb=jobCallbacks.get(job.id);if(cb&&['completed','failed','cancelled'].includes(job.status)){jobCallbacks.delete(job.id);if(job.status==='completed')Promise.resolve(cb(job.result)).catch(errorNotice);else errorNotice(new Error(job.error||t('Задание отменено','Job cancelled','Tarefa cancelada')));}if(activeView==='downloads')updateJobNode(job);}
