async function logsView(){const root=el('div',{},intro(t('Журнал мода','Mod logs','Registros do mod'),t('Локальный журнал текущего процесса. Секреты скрываются; журнал SWCH также доступен в карточке мода.','Local log for the current process. Secrets are redacted; SWCH logs are also available in the mod card.','Registro local do processo atual. Segredos são ocultados; os registros do SWCH também estão disponíveis no cartão do mod.')));const log=el('pre',{id:'live-log',text:(await api('logs.get')).join('\n')});root.append(form(t('Диагностика LumaCore','LumaCore diagnostics','Diagnóstico LumaCore'),'', [pathField('file','lumacore_diag.txt','file',['txt','log'])],input=>api('diagnostics.read',input)),el('div',{class:'toolbar'},button(t('Обновить','Refresh','Atualizar'),async()=>log.textContent=(await api('logs.get')).join('\n')),button(t('Копировать','Copy','Copiar'),()=>bridge.call('clipboard.writeText',{text:log.textContent}))),log);return root;}
