async function loadState(){state=await api('state');language=state.settings.language||'ru';$('.version').textContent=state.version;games=await api('games.list').catch(()=>[]);profile=await api('profile.get');applyTheme();$('#platform').textContent=state.platform;$('#connection').textContent=t('Подключено к SWCH','Connected to SWCH','Conectado ao SWCH');$('#foot-status').textContent='SDK '+state.sdk;const game=window.swch.game;if(game){$('#game-context').textContent=game.name;$('#game-context').hidden=false;}await refreshJobs();}
async function init(){if(!bridge){$('#main').replaceChildren(intro('SFF for SWCH',t('Откройте этот мод внутри SWCH 1.1. Здесь нет демонстрационного backend.','Open this mod inside SWCH SDK 1.1. There is no simulated backend.','Abra este mod no SWCH SDK 1.1. Não há backend simulado.')));return;}try{await loadState();bridge.on('jobs.changed',updateJob);bridge.on('sff.log',line=>{const node=$('#live-log');if(node)node.textContent=(node.textContent+'\n'+line).split('\n').slice(-500).join('\n');});bridge.on('drive.connected',()=>{toast(t('Google Drive подключён','Google Drive connected','Google Drive conectado'));if(activeView==='saves')void navigate();});bridge.on('drive.error',errorNotice);bridge.on('library.changed',()=>{void api('games.list').then(rows=>{games=rows;if(activeView==='library')void navigate();}).catch(errorNotice);});await navigate();pollTimer=setInterval(()=>void refreshJobs().catch(()=>{}),4000);}catch(error){$('#connection').textContent=t('Ошибка подключения','Connection failed','Falha de conexão');$('#main').replaceChildren(intro(t('Не удалось активировать SFF','Could not activate SFF','Não foi possível ativar SFF'),error.message),button(t('Повторить','Retry','Tentar novamente'),init));}}
window.addEventListener('hashchange',()=>void navigate());window.addEventListener('pagehide',()=>clearInterval(pollTimer));$('#menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#refresh').addEventListener('click',()=>{void loadState().then(navigate).catch(errorNotice);});$('#modal').addEventListener('click',event=>{if(event.target===$('#modal'))$('#modal').close();});void init();
